inline int horizontal_intent(bool left_pressed, bool right_pressed) noexcept {
    if (left_pressed == right_pressed) {
        return 0;
    }
    return left_pressed ? -1 : 1;
}

inline bool inside_board(const Piece& piece) noexcept {
    const auto cells = study_piece::to_board(piece);
    if (!cells.has_value()) {
        return false;
    }
    for (const auto& position : *cells) {
        if (!study_grid::Grid::contains(position.row, position.column)) {
            return false;
        }
    }
    return true;
}

inline Result try_shift(Piece& current, int direction) noexcept {
    // Only unit horizontal steps are meaningful to this layer.
    if (direction < -1 || direction > 1) {
        return Result::invalid;
    }

    // This exercise requires all current cells inside the board.
    // Hidden spawn rows and recovery from an outside state are separate policies.
    if (!inside_board(current)) {
        return Result::invalid;
    }

    if (direction == 0) {
        return Result::idle;
    }

    // Work on a copy so the caller's piece is never partially modified.
    Piece candidate = current;

    // Widen the origin column to 64 bits before adding so the range check
    // cannot itself overflow.
    const std::int64_t widened =
        static_cast<std::int64_t>(candidate.origin.column) +
        static_cast<std::int64_t>(direction);
    if (widened < static_cast<std::int64_t>(std::numeric_limits<int>::min()) ||
        widened > static_cast<std::int64_t>(std::numeric_limits<int>::max())) {
        return Result::invalid;
    }
    candidate.origin.column = static_cast<int>(widened);

    // Recompute the occupied cells for the shifted origin; a translation
    // failure here means the coordinate mapping is not usable.
    const auto cells = study_piece::to_board(candidate);
    if (!cells.has_value()) {
        return Result::invalid;
    }
    for (const auto& position : *cells) {
        if (!study_grid::Grid::contains(position.row, position.column)) {
            return Result::blocked;
        }
    }

    // Commit only after the candidate has been fully validated.
    current = candidate;
    return Result::moved;
}

const int direction = study_movement::horizontal_intent(
    platform_key_pressed(Key::Left), platform_key_pressed(Key::Right));
const auto move = study_movement::try_shift(piece, direction);
if (move == study_movement::Result::invalid) return 1;
if (move == study_movement::Result::moved) {
    const auto updated_cells = study_piece::to_board(piece);
    if (!updated_cells) return 1;
    const auto updated_mesh = study_piece_view::make_visible_mesh(*updated_cells);
    if (!piece_buffer.replace_same_size(updated_mesh.vertices.data(),
                                        updated_mesh.count)) return 1;
    std::printf("moved: column=%d (bounds only)\n", piece.origin.column);
} else if (move == study_movement::Result::blocked) {
    std::puts("blocked by board boundary; state unchanged");
}

bool VertexBuffer::replace_same_size(const study_mesh::Vertex2* vertices,
                                     std::size_t count) noexcept {
    if (name_ == 0 || !vertices || count_ <= 0 ||
        count != static_cast<std::size_t>(count_)) {
        return false;
    }
    // count_ was range-checked by upload; byte multiplication remains safe.
    const auto bytes = static_cast<GLsizeiptr>(count * sizeof(study_mesh::Vertex2));
    if (!stage_ok(gl_, "replace entry (pre-existing error)")) return false;
    gl_.BindBuffer(ArrayBuffer, name_);
    if (!stage_ok(gl_, "replace glBindBuffer")) return false;
    gl_.BufferData(ArrayBuffer, bytes, vertices, DynamicDraw);
    return stage_ok(gl_, "replace glBufferData");
}
